/* ---------- website saving ----------
   The website has no database. Arena picks made there are saved to one small file (arena.json) on the "picks"
   branch of the site's GitHub repo, using a key the owner pastes once and that is kept ONLY on that device
   (localStorage "cs-gh"; never in the repo, never in data.json). The scheduled runs copy that file into the
   dashboard database (run note A21), so both places end up with the same picks. */
var GH={repo:"smubizman/cover-story-site",branch:"picks",file:"arena.json",sha:null,data:{btm:{},surv:null,favs:null,bank:null,betpct:null},busy:false,dirty:false,wait:null,ok:false};
function ghTok(){try{return localStorage.getItem("cs-gh")||""}catch(e){return""}}
function ghHdr(){var h={Accept:"application/vnd.github+json"},t=ghTok();if(t)h.Authorization="Bearer "+t;return h}
function b64e(x){return btoa(unescape(encodeURIComponent(x)))}
function b64d(x){return decodeURIComponent(escape(atob(String(x).replace(/\s/g,""))))}
function ghApi(){return"https://api.github.com/repos/"+GH.repo+"/contents/"+GH.file}
function pstamp(r){if(!r)return"";var c=r.changes;return String(r.u||(c&&c.length?c[c.length-1].at:"")||r.at||"")}
function ghMerge(){var F=GH.data||{},B=F.btm||{};Object.keys(B).forEach(function(k){var x=B[k],cur=BTM[k];if(!x||x.kind!=="ats"||(x.mine!=="home"&&x.mine!=="away"))return;if(cur&&cur.gradedAt)return;if(!cur||pstamp(x)>=pstamp(cur))BTM[k]=x});
 try{var sv=F.surv,snapAt=String((((window.CS_SNAP||{}).surv||{}).game||{}).at||"");if(sv&&sv.you&&sv.you.picks&&String(sv.at||"")>snapAt)SV.you=sv.you}catch(e){}
 try{var fv=F.favs,fAt=String((((window.CS_SNAP||{}).ui||{}).favs||{}).at||"");if(fv&&Array.isArray(fv.teams)&&String(fv.at||"")>fAt)FAV=fv.teams}catch(e){}
 try{var bk=F.bank,bAt=String((((window.CS_SNAP||{}).ui||{}).bank||{}).at||"");if(bk&&Array.isArray(bk.adj)&&String(bk.at||"")>bAt)ADJ=bk.adj}catch(e){}
 try{if(pinAdopt(F.pins)){}}catch(e){}
 try{var bp=F.betpct,pAt=String((J(((window.CS_SNAP||{}).dash||{}).betpct)||{}).at||"");if(bp&&+bp.pct>0&&+bp.pct<=10&&String(bp.at||"")>pAt)D.betpct={pct:+bp.pct,at:bp.at}}catch(e){}}
async function ghLoad(){var t=ghTok(),d=null;
 if(t){var r=await fetch(ghApi()+"?ref="+GH.branch,{headers:ghHdr(),cache:"no-store"});if(r.status===404){GH.sha=null;d={}}else{if(!r.ok)throw new Error("load "+r.status);var j=await r.json();GH.sha=j.sha;d=JSON.parse(b64d(j.content))}}
 else{var r2=await fetch("https://raw.githubusercontent.com/"+GH.repo+"/"+GH.branch+"/"+GH.file+"?t="+Date.now(),{cache:"no-store"});if(!r2.ok)throw new Error("load "+r2.status);d=await r2.json()}
 GH.data={btm:(d&&d.btm)||{},surv:(d&&d.surv)||null,favs:(d&&d.favs)||null,bank:(d&&d.bank)||null,betpct:(d&&d.betpct)||null};GH.ok=true;ghMerge();if(!document.querySelector(".ov"))render()}
async function ghPut(n){var body={message:"Arena picks "+new Date().toISOString(),content:b64e(JSON.stringify({btm:GH.data.btm,surv:GH.data.surv,favs:GH.data.favs||null,bank:GH.data.bank||null,pins:GH.data.pins||null,betpct:GH.data.betpct||null,at:new Date().toISOString()})),branch:GH.branch};if(GH.sha)body.sha=GH.sha;
 var r=await fetch(ghApi(),{method:"PUT",headers:ghHdr(),body:JSON.stringify(body)});
 if((r.status===409||r.status===422)&&n<2){var mine=GH.data,r3=await fetch(ghApi()+"?ref="+GH.branch,{headers:ghHdr(),cache:"no-store"});if(!r3.ok)throw new Error("save "+r3.status);var j3=await r3.json(),rem=JSON.parse(b64d(j3.content));GH.sha=j3.sha;var RB=rem.btm||{};Object.keys(mine.btm).forEach(function(k){if(!RB[k]||pstamp(mine.btm[k])>=pstamp(RB[k]))RB[k]=mine.btm[k]});var nw=function(f){return mine[f]&&(!rem[f]||String(mine[f].at||"")>=String(rem[f].at||""))?mine[f]:rem[f]||null};GH.data={btm:RB,surv:nw("surv"),favs:nw("favs"),bank:nw("bank"),betpct:nw("betpct")};return ghPut(n+1)}
 if(!r.ok)throw new Error("save "+r.status);var j=await r.json();GH.sha=j.content&&j.content.sha}
function ghPush(){if(GH.busy){GH.dirty=true;return GH.wait}GH.busy=true;GH.wait=(async function(){try{do{GH.dirty=false;await ghPut(0)}while(GH.dirty)}finally{GH.busy=false}})();return GH.wait}
async function ghSave(path,rec){if(!ghTok())throw new Error("no key");if(!GH.ok)await ghLoad();var now=new Date().toISOString(),k,prev;
 if(path.indexOf("btm/")===0){k=path.slice(4);prev=GH.data.btm[k];rec.u=now;GH.data.btm[k]=JSON.parse(JSON.stringify(rec));try{await ghPush()}catch(e){if(prev)GH.data.btm[k]=prev;else delete GH.data.btm[k];throw e}}
 else if(path==="surv/game"){prev=GH.data.surv;GH.data.surv=JSON.parse(JSON.stringify(rec));try{await ghPush()}catch(e){GH.data.surv=prev;throw e}}
 else{var f1={"ui/favs":"favs","ui/bank":"bank","ui/pins":"pins","dash/betpct":"betpct"}[path];if(!f1)throw new Error("path");prev=GH.data[f1];GH.data[f1]=JSON.parse(JSON.stringify(rec));try{await ghPush()}catch(e){GH.data[f1]=prev;throw e}}}
